import{_ as t,o as n,c as i,a2 as o}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse(`{"title":"Loi sur la Protection de l'Environnement","description":"","frontmatter":{},"headers":[],"relativePath":"fr/46-环境保护法.md","filePath":"fr/46-环境保护法.md","lastUpdated":null}`),r={name:"fr/46-环境保护法.md"};function s(a,e,l,d,u,c){return n(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="loi-sur-la-protection-de-l-environnement" tabindex="-1">Loi sur la Protection de l&#39;Environnement <a class="header-anchor" href="#loi-sur-la-protection-de-l-environnement" aria-label="Permalink to &quot;Loi sur la Protection de l&#39;Environnement&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>46</td></tr><tr><td>Module</td><td>Système Juridique et Cadre de Gouvernance</td></tr><tr><td>Mots clés</td><td>Protection de l&#39;environnement, Origine de l&#39;Univers, Symbiose écologique, Développement durable, Prévention de la pollution</td></tr></tbody></table><h2 id="i-objectif-legislatif-et-principes-fondamentaux" tabindex="-1">I. Objectif Législatif et Principes Fondamentaux <a class="header-anchor" href="#i-objectif-legislatif-et-principes-fondamentaux" aria-label="Permalink to &quot;I. Objectif Législatif et Principes Fondamentaux&quot;">​</a></h2><p>La <em>Loi sur la Protection de l&#39;Environnement</em> est l&#39;une des cinq lois d&#39;accompagnement de la Civilisation Symbiotique de l&#39;Ancre. Elle vise à protéger l&#39;environnement écologique et l&#39;Origine de l&#39;Univers au sein de l&#39;Univers Hengyuan, à établir la philosophie de gouvernance environnementale de l&#39;« évolution symbiotique, développement durable », à empêcher la destruction de l&#39;écosystème cosmique par le développement prédateur, et à sauvegarder le fondement de survie pour la progression commune des Dix Mille Races.</p><p>Cette Loi établit les principes fondamentaux suivants :</p><table tabindex="0"><thead><tr><th>Principe</th><th>Contenu</th></tr></thead><tbody><tr><td>Protection de l&#39;Origine</td><td>L&#39;Origine de l&#39;Univers est le fondement de toute vie et de toute évolution ; elle doit être protégée en priorité ; l&#39;exploitation destructrice est interdite</td></tr><tr><td>Symbiose écologique</td><td>L&#39;humanité et la nature, toutes les races et les écosystèmes sont dans une relation symbiotique ; détruire l&#39;écologie, c&#39;est détruire son propre fondement de survie</td></tr><tr><td>Durabilité</td><td>Toutes les activités de développement doivent tenir compte des intérêts des générations présentes et futures ; contre l&#39;assèchement de l&#39;étang pour attraper tout le poisson</td></tr><tr><td>Prévention d&#39;abord</td><td>La protection de l&#39;environnement est orientée vers la prévention ; établit une institution d&#39;évaluation de l&#39;impact environnemental pour empêcher la pollution de se produire</td></tr><tr><td>Responsabilité du pollueur</td><td>Les entités qui causent la pollution de l&#39;environnement et la destruction écologique doivent supporter la responsabilité du traitement et de l&#39;indemnisation</td></tr><tr><td>Participation du public</td><td>Encourage la participation du public à la protection de l&#39;environnement ; garantit le droit du public à l&#39;information et à la participation environnementales</td></tr><tr><td>Coordination interplans</td><td>La protection de l&#39;environnement progresse en coordination entre les plans ; établit un mécanisme de coopération en gouvernance environnementale interplans</td></tr></tbody></table><h2 id="ii-portee-de-la-protection-de-l-environnement" tabindex="-1">II. Portée de la Protection de l&#39;Environnement <a class="header-anchor" href="#ii-portee-de-la-protection-de-l-environnement" aria-label="Permalink to &quot;II. Portée de la Protection de l&#39;Environnement&quot;">​</a></h2><p>La portée environnementale protégée par cette Loi comprend tous les écosystèmes et éléments environnementaux au sein de l&#39;Univers Hengyuan :</p><ol><li><strong>Environnement atmosphérique</strong> : y compris la concentration d&#39;énergie et l&#39;équilibre de composition de l&#39;atmosphère et des couches d&#39;énergie de chaque planète.</li><li><strong>Environnement hydrique</strong> : y compris la qualité et la quantité des eaux de surface, des eaux souterraines, des océans et des eaux énergétiques entre les plans.</li><li><strong>Environnement du sol</strong> : y compris la qualité du sol et la fertilité des sols terrestres et des veines minérales des ressources de culture.</li><li><strong>Diversité biologique</strong> : y compris la protection des espèces et des habitats de toutes les flores, faunes, micro-organismes et vies étranges.</li><li><strong>Environnement énergétique</strong> : y compris la concentration et l&#39;équilibre de distribution de l&#39;énergie spirituelle du ciel et de la terre, de l&#39;énergie originelle et des fragments de lois.</li><li><strong>Environnement spatial</strong> : y compris la stabilité spatiale des plans, les fissures spatiales et la sécurité environnementale de l&#39;espace plié.</li><li><strong>Environnement du domaine de conscience</strong> : y compris la propreté informationnelle de l&#39;espace de conscience collective et la prévention de la pollution spirituelle.</li></ol><h2 id="iii-institutions-principales" tabindex="-1">III. Institutions Principales <a class="header-anchor" href="#iii-institutions-principales" aria-label="Permalink to &quot;III. Institutions Principales&quot;">​</a></h2><h3 id="i-institution-d-evaluation-de-l-impact-environnemental" tabindex="-1">(I) Institution d&#39;Évaluation de l&#39;Impact Environnemental <a class="header-anchor" href="#i-institution-d-evaluation-de-l-impact-environnemental" aria-label="Permalink to &quot;(I) Institution d&#39;Évaluation de l&#39;Impact Environnemental&quot;">​</a></h3><p>Tous les projets de développement et de construction susceptibles d&#39;avoir un impact significatif sur l&#39;environnement doivent subir une évaluation de l&#39;impact environnemental avant le début des travaux. Le contenu de l&#39;évaluation comprend : l&#39;impact du projet sur les éléments environnementaux atmosphériques, hydriques, pédologiques, biologiques, énergétiques, spatiaux, etc., les mesures de prévention et d&#39;atténuation, l&#39;évaluation des risques environnementaux, etc. Les projets qui ne passent pas l&#39;évaluation de l&#39;impact environnemental ne doivent pas commencer la construction.</p><h3 id="ii-institution-de-permis-de-rejet-et-de-controle-des-quantites-totales" tabindex="-1">(II) Institution de Permis de Rejet et de Contrôle des Quantités Totales <a class="header-anchor" href="#ii-institution-de-permis-de-rejet-et-de-controle-des-quantites-totales" aria-label="Permalink to &quot;(II) Institution de Permis de Rejet et de Contrôle des Quantités Totales&quot;">​</a></h3><p>L&#39;État met en œuvre une gestion par permis et un contrôle des quantités totales pour les rejets de polluants. Les unités de rejet doivent obtenir des permis de rejet de polluants et rejeter les polluants conformément aux types, concentrations et quantités totales spécifiés dans les permis. L&#39;État détermine la quantité totale de rejets de polluants pour chaque région et chaque plan selon la capacité de charge environnementale, en la décomposant et en la mettant en œuvre niveau par niveau.</p><h3 id="iii-institution-des-lignes-rouges-de-protection-ecologique" tabindex="-1">(III) Institution des Lignes Rouges de Protection Écologique <a class="header-anchor" href="#iii-institution-des-lignes-rouges-de-protection-ecologique" aria-label="Permalink to &quot;(III) Institution des Lignes Rouges de Protection Écologique&quot;">​</a></h3><p>L&#39;État délimite des lignes rouges de protection écologique dans les zones à valeur écologique particulière, notamment :</p><table tabindex="0"><thead><tr><th>Type de ligne rouge</th><th>Contenu protégé</th></tr></thead><tbody><tr><td>Zone de protection de l&#39;Origine</td><td>Zones centrales de production de l&#39;énergie de l&#39;Origine de l&#39;Univers ; toutes les activités de développement sont interdites</td></tr><tr><td>Habitat des espèces</td><td>Habitats fondamentaux des espèces rares et menacées ; la destruction et la perturbation sont interdites</td></tr><tr><td>Zone de barrière écologique</td><td>Écosystèmes clés maintenant l&#39;équilibre écologique régional ; le développement est restreint</td></tr><tr><td>Lieux sacrés de culture</td><td>Zones riches en énergie à valeur de culture particulière ; une utilisation protectrice est mise en œuvre</td></tr><tr><td>Bande de jonction des plans</td><td>Zones de transition écologique entre les plans ; le développement destructeur de l&#39;espace est interdit</td></tr></tbody></table><h3 id="iv-institution-de-surveillance-et-d-alerte-precoce-de-l-environnement" tabindex="-1">(IV) Institution de Surveillance et d&#39;Alerte Précoce de l&#39;Environnement <a class="header-anchor" href="#iv-institution-de-surveillance-et-d-alerte-precoce-de-l-environnement" aria-label="Permalink to &quot;(IV) Institution de Surveillance et d&#39;Alerte Précoce de l&#39;Environnement&quot;">​</a></h3><p>L&#39;État établit un réseau de surveillance de l&#39;environnement couvrant tout l&#39;univers, surveillant en temps réel les changements des éléments environnementaux. Pour les événements majeurs de pollution de l&#39;environnement et de destruction écologique susceptibles de se produire, un mécanisme d&#39;alerte précoce est établi, émettant rapidement des informations d&#39;alerte et déclenchant une réponse d&#39;urgence.</p><h3 id="v-institution-de-compensation-ecologique" tabindex="-1">(V) Institution de Compensation Écologique <a class="header-anchor" href="#v-institution-de-compensation-ecologique" aria-label="Permalink to &quot;(V) Institution de Compensation Écologique&quot;">​</a></h3><p>Les régions et les groupes dont le développement est restreint en raison de la protection de l&#39;environnement ont le droit de recevoir une compensation écologique. Les fonds de compensation écologique sont prélevés sur l&#39;accumulation publique et les revenus de l&#39;exploitation des ressources, utilisés pour le développement économique des régions compensées et l&#39;amélioration de la vie des habitants.</p><h2 id="iv-reglementation-environnementale-des-activites-de-culture" tabindex="-1">IV. Réglementation Environnementale des Activités de Culture <a class="header-anchor" href="#iv-reglementation-environnementale-des-activites-de-culture" aria-label="Permalink to &quot;IV. Réglementation Environnementale des Activités de Culture&quot;">​</a></h2><p>L&#39;impact des activités de culture sur l&#39;environnement est un domaine particulier de la protection de l&#39;environnement dans l&#39;Univers Hengyuan ; cette Loi établit des dispositions réglementaires dédiées :</p><ol><li><strong>Réglementation de l&#39;extraction d&#39;énergie</strong> : l&#39;extraction des ressources de culture doit se conformer au principe de durabilité ; l&#39;extraction destructrice conduisant à l&#39;épuisement de l&#39;énergie est interdite. Le volume d&#39;extraction ne doit pas dépasser le taux de régénération naturelle de l&#39;énergie régionale.</li><li><strong>Traitement des déchets de culture</strong> : les résidus d&#39;énergie, les pilules jetées, les artefacts endommagés et autres déchets générés pendant la culture doivent être traités conformément aux règlements ; le rejet aléatoire causant une pollution énergétique est interdit.</li><li><strong>Évaluation environnementale de la culture avancée</strong> : les percées et les retraites des cultivateurs avancés peuvent avoir des impacts significatifs sur l&#39;environnement environnant ; une évaluation environnementale doit être réalisée à l&#39;avance et des mesures de protection prises.</li><li><strong>Permis de développement des plans</strong> : le développement de nouveaux plans doit subir une évaluation environnementale et une enquête écologique ; le développement ne peut être entrepris qu&#39;après l&#39;élaboration d&#39;un plan de protection écologique.</li><li><strong>Protection des habitats des vies étranges</strong> : les habitats des vies étranges sont inclus dans les lignes rouges de protection écologique ; l&#39;exploration et le développement sans autorisation sont interdits.</li></ol><h2 id="v-responsabilite-juridique" tabindex="-1">V. Responsabilité Juridique <a class="header-anchor" href="#v-responsabilite-juridique" aria-label="Permalink to &quot;V. Responsabilité Juridique&quot;">​</a></h2><p>Les actes violant les dispositions de cette Loi supportent les responsabilités suivantes selon la gravité des circonstances :</p><ul><li>Ceux qui commencent la construction sans passer l&#39;évaluation de l&#39;impact environnemental sont ordonnés d&#39;arrêter la construction, de restaurer l&#39;état d&#39;origine et amendés.</li><li>Ceux qui rejettent des polluants au-delà des normes sont ordonnés de traiter dans un délai et amendés ; dans les cas graves, ordonnés de suspendre les opérations et de fermer.</li><li>Ceux qui détruisent les lignes rouges de protection écologique sont ordonnés de restaurer l&#39;état d&#39;origine et amendés ; dans les cas graves, la responsabilité pénale est poursuivie.</li><li>Ceux qui extraient destructivement les ressources de culture ont leurs gains illégaux confisqués et sont amendés ; leurs permis d&#39;extraction sont révoqués.</li><li>Ceux qui causent des accidents majeurs de pollution de l&#39;environnement supportent la responsabilité d&#39;indemnisation ; en cas d&#39;infraction pénale, la responsabilité pénale est poursuivie.</li><li>Les personnels de surveillance environnementale qui négligent leurs devoirs ou abusent de leur pouvoir sont sanctionnés ; en cas d&#39;infraction pénale, la responsabilité pénale est poursuivie.</li></ul><h2 id="vi-participation-du-public-et-action-d-interet-public-environnementale" tabindex="-1">VI. Participation du Public et Action d&#39;Intérêt Public Environnementale <a class="header-anchor" href="#vi-participation-du-public-et-action-d-interet-public-environnementale" aria-label="Permalink to &quot;VI. Participation du Public et Action d&#39;Intérêt Public Environnementale&quot;">​</a></h2><p>Le public a le droit de participer à la protection de l&#39;environnement, avec des canaux spécifiques comprenant :</p><ol><li>Soumettre des opinions et des suggestions sur les projets d&#39;évaluation de l&#39;impact environnemental.</li><li>Signaler et dénoncer les actes de pollution de l&#39;environnement et de destruction de l&#39;écologie.</li><li>Établir des organisations de protection de l&#39;environnement conformément à la loi, participer à la surveillance environnementale et aux activités d&#39;intérêt public.</li><li>Pour les actes qui polluent l&#39;environnement, détruisent l&#39;écologie et nuisent aux intérêts publics, les organisations de protection de l&#39;environnement peuvent intenter une action d&#39;intérêt public environnementale devant le Tribunal Symbiotique.</li></ol><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>La <em>Loi sur la Protection de l&#39;Environnement</em> est la garantie juridique de la philosophie de développement durable de la Civilisation Symbiotique de l&#39;Ancre. En établissant des institutions telles que l&#39;évaluation de l&#39;impact environnemental, les lignes rouges de protection écologique et le contrôle des quantités totales, elle intègre la protection de l&#39;environnement dans toutes les activités de développement et de culture, assurant la durabilité de l&#39;Origine de l&#39;Univers et de l&#39;écosystème, et gardant le fondement éternel de survie pour la progression commune des Dix Mille Races.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Constitution Symbiotique : Principes Généraux)</li><li>39-住房与环境保障 (Logement et Protection de l&#39;Environnement)</li><li>15-能量循环与转化法则 (Loi de la Circulation et de la Transformation de l&#39;Énergie)</li><li>53-奇特生命识别标准 (Normes d&#39;Identification des Vies Étranges)</li></ul>',34)])])}const v=t(r,[["render",s]]);export{m as __pageData,v as default};
